'use client'

import * as React from 'react'

import { Stat, type StatPresentation } from './stat'


/**
 * Round: "round 2 of 5", drawn as a row of pips.
 *
 * A number and a ceiling. It performs nothing, it decides nothing, and it adds
 * no rendering of its own: `stat` already knows that a value with a max reads
 * as "2 of 5" to a screen reader, and since GSUI-100 it knows how to draw that
 * as a row of segment pills — done, current, coming. This exists so that a host
 * writes `<Round value={2} max={5} />` instead of remembering which `kind` a
 * round is, and so that a test can find the round on a surface that also
 * carries a score and a timer.
 *
 * Without a `max` there is no sequence to draw, so the pips degrade to the bare
 * number. A round with no known total is a real case — an endless mode — and it
 * should render rather than throw.
 */

export interface RoundProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /** Which round this is. 1-based, like every other position in the contract. */
  value: number
  /** How many rounds there are, when that is known in advance. */
  max?: number
  /** The word beside the number. Defaults to `round`. */
  label?: string
  /** The silhouette. A row of pips is what the design draws. */
  presentation?: StatPresentation
}

export function Round({
  value,
  max,
  label,
  presentation = 'pips',
  className,
  ...rest
}: RoundProps) {
  return (
    // No wrapper: `stat` takes `component` as a prop now, so round names its
    // own root without a second element.
    <Stat
      {...rest}
      className={className}
      component="round"
      kind="round"
      value={value}
      max={max}
      label={label}
      presentation={presentation}
    />
  )
}
